    if(kicker){ctx.fillStyle=ac.bar;ctx.textAlign="left";ctx.font=`700 ${Math.round(U*0.032)}px Inter, sans-serif`;ctx.fillText(kicker.toUpperCase(),aX+aW*0.05,aY);aY+=U*0.07;}
    ctx.fillStyle="#fff"; ctx.textAlign="left";
